using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.Intelligence;
public sealed class InstrumentSignal:EntityBase{public Guid SignalId{get;set;}public string InstrumentToken{get;set;}="";public DateTimeOffset SignalTime{get;set;}public string Direction{get;set;}="Neutral";public string Strength{get;set;}="Neutral";public decimal Confidence{get;set;}public decimal? ExpectedMoveMin{get;set;}public decimal? ExpectedMoveMax{get;set;}public decimal RiskScore{get;set;}public string? MarketRegime{get;set;}public string ModelVersion{get;set;}="v1";public string ReasonsJson{get;set;}="[]";}
public sealed class IntelligenceDbContext(DbContextOptions<IntelligenceDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<InstrumentSignal>Signals=>Set<InstrumentSignal>();protected override void OnModelCreating(ModelBuilder m) => ConfigureModel(m); public static void ConfigureModel(ModelBuilder m) {m.HasDefaultSchema("intelligence");ConfigureEntity(m.Entity<InstrumentSignal>());m.Entity<InstrumentSignal>().HasIndex(x=>x.SignalId).IsUnique();m.Entity<InstrumentSignal>().HasIndex(x=>new{x.InstrumentToken,x.SignalTime});}}
public static class IntelligenceModule{public static IServiceCollection AddIntelligenceModule(this IServiceCollection s,string cs){s.AddDbContext<IntelligenceDbContext>(o=>o.UseNpgsql(cs));return s;}}
